<script setup lang="ts">
import {getRequestError} from '~/utils/errors'
definePageMeta({layout:false})
useSeoMeta({title:'Accept admin invitation · BARNALI',robots:'noindex,nofollow'})
const route=useRoute();const api=useApi();const name=ref('');const username=ref('');const password=ref('');const busy=ref(false);const error=ref('');const message=ref('')
async function submit(){if(typeof route.query.token!=='string'){error.value='This invitation link is missing its token.';return}busy.value=true;error.value='';try{const result=await api.request<{message:string}>('/auth/admin-invitations/accept',{method:'POST',body:{token:route.query.token,displayName:name.value,username:username.value,password:password.value}});message.value=result.message}catch(e:unknown){error.value=getRequestError(e,'This invitation could not be accepted. It may have expired or been revoked.')}finally{busy.value=false}}
</script>
<template><main class="auth-panel-wrap"><section class="auth-panel surface surface-pad"><BarnaliBrand compact/><span class="eyebrow">Administrator invitation</span><h1 class="serif-title">Set up your access</h1><p class="muted">Choose your own account details. Existing accounts must confirm their current password. The invitation is single-use and expires after 7 days.</p><p v-if="message" class="notice notice--success" role="status">{{message}} <NuxtLink to="/admin/login">Administrator sign in</NuxtLink></p><p v-if="error" class="notice notice--error" role="alert">{{error}}</p><form class="auth-form" @submit.prevent="submit"><div class="form-field"><label for="invite-name">Display name</label><input id="invite-name" v-model="name" class="input" maxlength="80" required></div><div class="form-field"><label for="invite-username">Username</label><input id="invite-username" v-model="username" class="input" pattern="[A-Za-z0-9_]{3,32}" minlength="3" maxlength="32" required></div><div class="form-field"><label for="invite-password">{{'Account password (or choose one if new)'}}</label><input id="invite-password" v-model="password" class="input" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></div><button class="btn" :disabled="busy||!!message">{{busy?'Accepting…':'Accept invitation'}}</button></form></section></main></template>
